# ecx, esi -> thiscall, ret 0); o método +0x3c da vtable (push 0; push &+0x3a; push &+0x3c; push -1; mov ecx, esi ->
# thiscall, ret 0x10); Cup::map_fixture_tree 0x518790 (mov ecx, esi -> thiscall, ret 0); operator new 0x944cf1 (push
# 0x5ce; add esp, 4 -> cdecl); Comp_Stats::Comp_Stats 0x49ee70 (push esi; mov ecx, eax -> thiscall, ret 4);
# Cup::rank_teams 0x5223a0 (mov ecx, esi -> thiscall, ret 0); FraLgeCup::collect_entrants 0x5bd160 (mov ecx, esi ->
